const ord = $input.first().json;
const sanitize = (str) => str ? str.replace(/[\x00-\x1F]/g, "").substring(0, 5000) : null;

if (ord.note) ord.note = sanitize(ord.note);
if (ord.email) ord.email = sanitize(ord.email);
if (ord.referring_site) ord.referring_site = sanitize(ord.referring_site);
if (ord.landing_site) ord.landing_site = sanitize(ord.landing_site);

if (ord.customer) {
  ord.customer.first_name = sanitize(ord.customer.first_name);
  ord.customer.last_name = sanitize(ord.customer.last_name);
  ord.customer.email = sanitize(ord.customer.email);
  ord.customer.phone = sanitize(ord.customer.phone);
  if (ord.customer.default_address) {
    ord.customer.default_address.city = sanitize(ord.customer.default_address.city);
    ord.customer.default_address.province = sanitize(ord.customer.default_address.province);
  }
}

if (ord.line_items) {
  for (const li of ord.line_items) {
    li.title = sanitize(li.title);
    li.variant_title = sanitize(li.variant_title);
    li.sku = sanitize(li.sku);
  }
}

// Atribucion UTM se maneja desde shopify_customer_journeys (E5A)

return [{ json: ord }];

const r = $input.first().json;
// Sanea texto libre (patron AIR-94): elimina tags y caracteres de control, trunca.
const sanitize = (str) => str
  ? String(str).replace(/[\x00-\x1F\x7F]/g, " ").replace(/<[^>]*>/g, "").substring(0, 5000)
  : null;
const num = (v) => { const n = parseFloat(v); return Number.isFinite(n) ? n : 0; };

const rli = Array.isArray(r.refund_line_items) ? r.refund_line_items : [];
const adj = Array.isArray(r.order_adjustments) ? r.order_adjustments : [];

let subtotal = 0;
let impuesto = 0;
const refund_line_items = rli.map((li) => {
  const li_subtotal = num(li.subtotal ?? li.subtotal_set?.shop_money?.amount);
  const li_tax = num(li.total_tax ?? li.total_tax_set?.shop_money?.amount);
  subtotal += li_subtotal;
  impuesto += li_tax;
  return {
    shopify_refund_line_item_id: li.id != null ? String(li.id) : null,
    shopify_line_item_id: li.line_item_id != null ? String(li.line_item_id) : null,
    cantidad: parseInt(li.quantity, 10) || 0,
    monto: li_subtotal,
    restock_type: li.restock_type || null,
  };
});

// order_adjustments: shipping_refund y ajustes de impuesto (montos negativos = dinero devuelto).
let envio = 0;
for (const a of adj) {
  if (a.kind === "shipping_refund") envio += Math.abs(num(a.amount));
  impuesto += Math.abs(num(a.tax_amount));
}

const total = subtotal + impuesto + envio;

const payload = {
  shopify_refund_id: r.id != null ? String(r.id) : null,
  shopify_order_id: r.order_id != null ? String(r.order_id) : null,
  fecha_refund: r.created_at || r.processed_at || null,
  nota: sanitize(r.note),
  subtotal,
  impuesto,
  envio,
  total,
  refund_line_items,
};

return [{ json: payload }];
